# Copies the newest CHANGELOG.md entries into WhatsNew.generated.ahk so What's new works offline.
# Run after every CHANGELOG.md edit. -Check exits 1 when the generated file is out of date.
param([switch]$Check, [int]$Versions = 15)
$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$source = Join-Path $root 'CHANGELOG.md'
$target = Join-Path $root 'WhatsNew.generated.ahk'

# Keep everything from the first version heading through the newest $Versions versions.
$lines = [IO.File]::ReadAllText($source, [Text.Encoding]::UTF8) -replace "`r", '' -split "`n"
$kept = New-Object System.Collections.Generic.List[string]
$seen = 0
foreach ($line in $lines) {
    if ($line -match '^## ') { $seen++ }
    if ($seen -eq 0) { continue }
    if ($seen -gt $Versions) { break }
    $kept.Add($line)
}
while ($kept.Count -and $kept[$kept.Count - 1] -eq '') { $kept.RemoveAt($kept.Count - 1) }

# AHK string escapes: backtick first, then quote and semicolon.
$body = foreach ($line in $kept) {
    $escaped = $line.Replace('`', '``').Replace('"', '`"').Replace(';', '`;')
    '        . "' + $escaped + '`n"'
}
$text = @(
    '; Generated by tools\Build-WhatsNew.ps1 from CHANGELOG.md. Do not edit by hand.'
    'WhatsNewSource() {'
    '    return ""'
) + $body + @('}', '') -join "`r`n"

$current = if (Test-Path $target) { [IO.File]::ReadAllText($target) -replace "`r", '' } else { $null }
if ($Check) {
    if ($current -ne ($text -replace "`r", '')) { Write-Output 'WhatsNew.generated.ahk is out of date.'; exit 1 }
    exit 0
}
[IO.File]::WriteAllText($target, $text, (New-Object Text.UTF8Encoding $true))
Write-Output "Wrote $target ($($kept.Count) lines)"
